 "content": "from collections import deque


def transform(grid):
    """Recolor every 4-connected zero component of size >= 2 to 8."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                x, y = q.popleft()
                component.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if len(component) >= 2:
                for x, y in component:
                    out[x][y] = 8
    return out
